def _candidate_roots():
    roots = []
    for raw in (
        os.path.dirname(os.path.realpath(__file__)),
        os.path.dirname(os.path.abspath(__file__)),
        os.getcwd(),
    ):
        if raw and raw not in roots:
            roots.append(raw)
    # البحث في الأب المباشر عند تشغيل main.py من مجلد مختلف.
    for r in list(roots):
        parent = os.path.dirname(r)
        if parent and parent not in roots:
            roots.append(parent)
    return roots

BASE_DIR = next((r for r in _candidate_roots() if os.path.isfile(os.path.join(r, "main.py"))), os.path.dirname(os.path.realpath(__file__)))

# نسخ مضمّنة من الخطين الأساسيين لضمان عدم ظهور مربعات عربية حتى عند نقل الملف.
_EMBEDDED_FONTS = {
    "Cairo-Regular.ttf": "",
    "NotoSansArabic.ttf": "",
}

def _embedded_font_path(filename):
    """يعيد خطاً مضموناً؛ يستخرج الخط المضمّن عند غياب ملف assets."""
    payload = _EMBEDDED_FONTS.get(filename)
    if not payload:
        return ""
    try:
        cache_dir = os.path.join(tempfile.gettempdir(), "ALBADR_FONT_CACHE")
        os.makedirs(cache_dir, exist_ok=True)
        target = os.path.join(cache_dir, filename)
        if not os.path.isfile(target) or os.path.getsize(target) < 1024:
            data = zlib.decompress(base64.b64decode(payload.encode("ascii")))
            with open(target, "wb") as fh:
                fh.write(data)
        return target if os.path.isfile(target) else ""
    except Exception:
        return ""

def _find_asset(*parts):
    for root in _candidate_roots():
        path = os.path.join(root, *parts)
        if os.path.isfile(path):
            return path
    return ""

CAIRO_REGULAR_FILE = _find_asset("assets", "fonts", "Cairo-Regular.ttf") or _embedded_font_path("Cairo-Regular.ttf")
