class ArabicSpinnerOption(SpinnerOption):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.font_name = FONT_NAME
        self.halign = "right"
        direction = _text_direction(getattr(self, "text", "")) if "_text_direction" in globals() else "rtl"
        for prop, value in (("base_direction", direction), ("font_direction", direction),
                            ("font_script_name", "Arab" if direction == "rtl" else "Latn"),
                            ("text_language", "ar" if direction == "rtl" else "en")):
            if hasattr(self, prop):
                try:
                    setattr(self, prop, value)
                except Exception:
                    pass


class Popup(KivyPopup):
    """Popup عربي: يفرض الخط العربي على عنوان النافذة وكل عناصرها."""
    def on_open(self, *args):
        super().on_open(*args)
        def apply(widget):
            try:
                if isinstance(widget, ArabicTextField):
                    widget.font_name = FIELD_FONT_NAME
                    direction = _text_direction(widget.get_logical_text())
                elif hasattr(widget, "font_name") and widget.__class__.__name__ not in ("MDIcon", "IconLeftWidget", "IconRightWidget"):
                    widget.font_name = FONT_NAME
                    direction = _text_direction(getattr(widget, "text", ""))
                else:
                    direction = _text_direction(getattr(widget, "text", ""))
                for prop, value in (("base_direction", direction), ("font_direction", direction),
                                    ("font_script_name", "Arab" if direction == "rtl" else "Latn"),
                                    ("text_language", "ar" if direction == "rtl" else "en")):
                    if hasattr(widget, prop):
                        try:
                            setattr(widget, prop, value)
                        except Exception:
                            pass
            except Exception:
                pass
            for child in list(getattr(widget, "children", [])):
                apply(child)
        Clock.schedule_once(lambda dt: apply(self), 0)
        Clock.schedule_once(lambda dt: apply(self), .08)


def arabic_spinner(**kwargs):
    kwargs.setdefault("option_cls", ArabicSpinnerOption)
    sp = Spinner(**kwargs)
    sp.font_name = FONT_NAME
    return sp


