HIJRI_MONTHS = [
    "محرم", "صفر", "ربيع الأول", "ربيع الثاني", "جمادى الأولى", "جمادى الثانية",
    "رجب", "شعبان", "رمضان", "شوال", "ذو القعدة", "ذو الحجة"
]
# يطابق التاريخ المحلي المتفق عليه: 2026-08-18 => 5/ربيع الأول/1448
HIJRI_LOCAL_OFFSET = 2


def gregorian_to_hijri(g_date):
    jd = g_date.toordinal() + 1721424.5
    l = int(jd) - 1948440 + 10632
    n = (l - 1) // 10631
    l = l - 10631 * n + 354
    j = ((10985 - l) // 5316) * ((50 * l) // 17719) + (l // 5670) * ((43 * l) // 15238)
    l = l - ((30 - j) // 15) * ((17719 * j) // 50) - (j // 16) * ((15238 * j) // 43) + 29
    m = (24 * l) // 709
    d = l - (709 * m) // 24
    y = 30 * n + j - 30
    return y, m, d


def hijri_today():
    return gregorian_to_hijri(date.today() + timedelta(days=HIJRI_LOCAL_OFFSET))


def hijri_text(y, m, d):
    return f"{d}/{HIJRI_MONTHS[m - 1]}/{y}"


def hijri_key(value):
    try:
        text = str(value or "").strip()
        d, month, y = text.split("/", 2)
        return int(y), HIJRI_MONTHS.index(month) + 1, int(d)
    except Exception:
        return (0, 0, 0)


def days_in_hijri_month(year, month):
    return 30 if month % 2 == 1 else 29


