def clone_default():
    return json.loads(json.dumps(DEFAULT_SETTINGS, ensure_ascii=False))


def load_json(path, default):
    try:
        if not os.path.exists(path):
            return default
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception as exc:
        print("LOAD ERROR", path, exc)
        return default


def save_json(path, value):
    tmp = path + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(value, f, ensure_ascii=False, indent=2)
        os.replace(tmp, path)
        return True
    except Exception as exc:
        print("SAVE ERROR", path, exc)
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass
        return False


def normalize_field(cfg):
    """Normalize old/new field settings without ever crashing startup.

    Older ALBADR builds stored layout as words such as ``single``/``double``/
    ``triple`` while the current build uses 1/2/3.  Settings are user data,
    so a malformed value must never be allowed to close the whole application.
    """
    cfg = dict(cfg or {})
    key = str(cfg.get("key", "")).strip()
    label = str(cfg.get("label", key)).strip()

    raw_layout = cfg.get("layout", 1 if key in ("name", "procedures") else 2)
    layout_map = {
        "single": 1, "one": 1, "1": 1, "أحادي": 1, "احادي": 1,
        "double": 2, "two": 2, "2": 2, "ثنائي": 2, "ثنائي": 2,
        "triple": 3, "three": 3, "3": 3, "ثلاثي": 3,
    }
    try:
        if isinstance(raw_layout, str):
            normalized = raw_layout.strip().lower()
            layout = layout_map.get(normalized)
            if layout is None:
                layout = int(float(normalized))
        else:
            layout = int(raw_layout)
    except (TypeError, ValueError):
        layout = 1 if key in ("name", "procedures") else 2
    layout = min(3, max(1, layout))
    if key in ("name", "procedures"):
        layout = 1
    return {
        "key": key,
        "label": label or key,
        "required": bool(cfg.get("required", False)),
        "enabled": bool(cfg.get("enabled", True)),
        "long": bool(cfg.get("long", False)),
        "layout": layout,
        "system": bool(cfg.get("system", False)),
        "date": bool(cfg.get("date", False)),
    }


def get_settings():
    raw = load_json(SETTINGS_FILE, None)
    s = clone_default()
    if isinstance(raw, dict):
        s.update(raw)
    fields = []
    raw_fields = s.get("fields") if isinstance(s.get("fields"), list) else []
    seen = set()
    for item in raw_fields:
        n = normalize_field(item)
        if n["key"] and n["key"] not in seen and n["key"] not in ("hijri_date",):
            fields.append(n)
            seen.add(n["key"])
    # تحويل الحقل القديم إلى تاريخ التسجيل النظامي.
    if "registration_date" not in seen:
        fields.insert(0, {"key": "registration_date", "label": "تاريخ التسجيل", "required": True, "enabled": True, "long": False, "layout": 2, "system": True, "date": True})
        seen.add("registration_date")
    # نضيف الافتراضيات الجديدة فقط إذا لم تكن موجودة، دون حذف حقول المستخدم.
    for item in DEFAULT_FIELDS:
        n = normalize_field(item)
        if n["key"] not in seen:
            fields.append(n)
            seen.add(n["key"])
    # تأكيد خصائص الحقول الأساسية.
    for f in fields:
        if f["key"] == "registration_date":
            f["system"] = True; f["date"] = True; f["required"] = True
        if f["key"] in ("injury_date", "return_date"):
            f["date"] = True
        if f["key"] in ("name", "procedures"):
            f["layout"] = 1
    s["fields"] = fields
    # تطبيع هوية المركز دون التأثير على النسخ القديمة.
    cp = clone_default().get("center_profile", {}).copy()
    if isinstance(s.get("center_profile"), dict):
        cp.update(s.get("center_profile") or {})
    cp["center_id"] = str(cp.get("center_id", "") or "").strip()
    cp["center_name"] = str(cp.get("center_name", "") or "").strip()
    cp["center_code"] = str(cp.get("center_code", "") or "").strip()
    s["center_profile"] = cp
    rpt = clone_default()["report"]
    if isinstance(s.get("report"), dict):
        rpt.update(s["report"])
    if "cover_rows" not in rpt:
        old = rpt.get("cover_body", "")
        rpt["cover_rows"] = (str(old).splitlines() + [""] * 6)[:6]
    if "data_orientation" not in rpt:
        rpt["data_orientation"] = rpt.get("table_orientation", "landscape")
    if "cover_orientation" not in rpt:
        rpt["cover_orientation"] = "portrait"
    if "header_visible" not in rpt: rpt["header_visible"] = True
    if "footer_visible" not in rpt: rpt["footer_visible"] = True
    if "header_logo_visible" not in rpt: rpt["header_logo_visible"] = True
    if str(rpt.get("font_name", "")).strip().lower() != "notosansarabic": rpt["font_name"] = "NotoSansArabic"
    # بنية مرنة للتذييل: 3 أعمدة × صفين، مع توافق مع القيم القديمة.
    for side in ("left", "center", "right"):
        key = f"footer_{side}_lines"
        if not isinstance(rpt.get(key), list):
            rpt[key] = [str(rpt.get(f"footer_{side}", "") or ""), ""]
        rpt[key] = [str(x) for x in rpt.get(key, [])[:2]] + [""] * max(0, 2-len(rpt.get(key, [])))
    rpt.setdefault("header_shift_percent", -2.0)
    rpt.setdefault("header_left_inset_percent", 5.0)
    rpt.setdefault("organization_name", "")
    rpt.setdefault("report_bold", False)
    # سياسة التذييل المعتمدة: 3 أعمدة × صفين.
    if not rpt.get("footer_left_lines") or rpt.get("footer_left_lines") == ["المسؤول / __________", ""]:
        rpt["footer_left_lines"] = ["المختص", "وعد الله النصيري"]
    if not rpt.get("footer_center_lines") or rpt.get("footer_center_lines") == ["", ""]:
        rpt["footer_center_lines"] = ["------", "-------"]
    if not isinstance(rpt.get("footer_right_lines"), list):
        rpt["footer_right_lines"] = ["", ""]
    rpt["footer_left"] = (rpt.get("footer_left_lines") or ["المختص"])[0] if rpt.get("footer_left_lines") else "المختص"
    rpt["footer_center"] = (rpt.get("footer_center_lines") or ["------"])[0] if rpt.get("footer_center_lines") else "------"
    rpt["footer_right"] = (rpt.get("footer_right_lines") or [""])[0] if rpt.get("footer_right_lines") else ""
    # 111111 was the old prototype table-header default; migrate it to the
    # light blue professional header used by the approved report model.
    if str(rpt.get("table_header_color", "")).replace("#", "").upper() == "111111":
        rpt["table_header_color"] = "BFE7F5"
    s["report"] = rpt
    return s


def load_records():
    data = load_json(DATA_FILE, [])
    if isinstance(data, dict):
        data = data.get("records", [])
    return data if isinstance(data, list) else []


def save_records(records):
    return save_json(DATA_FILE, records)


# ============================================================
# RTL والنصوص — عرض UI بالنص العربي الأصلي
# ============================================================
# مهم: لا نستخدم arabic_reshaper داخل واجهة Kivy.
# Cairo يعتمد على OpenType shaping، وإجبار النص على Presentation Forms
# ينتج مربعات لبعض الحروف (خصوصًا الألف/اللام) لأن الخط يعتمد على
# تشكيل OpenType بدل تخزين كل شكل منفصلًا. نرسل Unicode العربي الأصلي
# إلى محرك Kivy مع اتجاه RTL ونترك المحرك يقوم بالتشكيل.
def ar(text):
    if text is None:
        return ""
    return str(text)


def _shape_report_arabic(text):
    """تشكيل خاص بالتصدير النصي الذي لا يقوم بتشكيل العربية تلقائيًا."""
    if not text:
        return ""
    try:
        reshaper = arabic_reshaper.ArabicReshaper(configuration={
            "delete_harakat": True,
            "delete_tatweel": False,
            "support_ligatures": False,
            "support_zwj": True,
            "shift_harakat_position": False,
            "use_unshaped_instead_of_isolated": False,
        })
        return get_display(reshaper.reshape(str(text)), base_dir="R")
    except Exception:
        try:
            return get_display(arabic_reshaper.reshape(str(text)), base_dir="R")
        except Exception:
            return str(text)


def report_ar(text):
    return _shape_report_arabic(text)


class ArabicTextField(MDTextField):
    """حقل عربي يعمل بمسار Unicode منطقي منفصل عن النص المرئي.

    Kivy 2.3.1 على Android/Pydroid قد يعكس تسلسل العربية داخل TextInput
    عند استخدام base_direction/font_direction مع النص المنطقي مباشرة. لذلك
    لا نضع get_display داخل القيمة المخزنة. القيمة المنطقية تبقى سليمة، بينما
    النص المرئي فقط يُرسم بعد shaping مرة واحدة. هذا يعالج أيضًا فتح السجل
    للتعديل: set_logical_text يعيد بناء العرض الصحيح من القيمة الأصلية.
    """
    _BIDI_MARKS = "\u200e\u200f\u202a\u202b\u202c\u202d\u202e\u2066\u2067\u2068\u2069"

    def __init__(self, **kwargs):
        self.logical_text = ""
        self._visual_updating = False
        self._date_visual = False
        super().__init__(**kwargs)
        self.halign = "right"
        try:
            self.base_direction = "ltr"
            self.font_direction = "ltr"
            self.font_script_name = "Arab"
            self.text_language = "ar"
        except Exception:
            pass
        self.font_name = FIELD_FONT_NAME
        self.font_name_hint_text = FIELD_FONT_NAME

    @classmethod
    def _clean(cls, value):
        return "".join(ch for ch in str(value or "") if ch not in cls._BIDI_MARKS)

    @staticmethod
    def _has_arabic(text):
        for ch in str(text or ""):
            o = ord(ch)
            if (0x0600 <= o <= 0x06FF) or (0x0750 <= o <= 0x077F) or (0x08A0 <= o <= 0x08FF) or (0xFB50 <= o <= 0xFDFF) or (0xFE70 <= o <= 0xFEFF):
                return True
        return False

    def get_logical_text(self):
        return self._clean(self.logical_text)

    def set_logical_text(self, value):
        self.logical_text = self._clean(value)
        self._refresh_visual()

    def _refresh_visual(self):
        """Render editable fields without changing the global UI direction policy.

        Android's Kivy TextInput path used by this project does not reliably
        perform Arabic OpenType shaping inside editable controls.  Therefore
        Arabic input is shaped *only inside ArabicTextField*.  Labels and the
        rest of the UI remain untouched, so the English-direction fix is not
        affected.
        """
        logical = self.logical_text
        has_ar = self._has_arabic(logical)

        if has_ar:
            try:
                # Build connected Arabic glyphs for TextInput's renderer.
                # get_display supplies visual RTL order; the widget itself is
                # kept LTR to prevent Kivy from applying bidi a second time.
                reshaper = arabic_reshaper.ArabicReshaper(configuration={
                    "delete_harakat": False,
                    "delete_tatweel": False,
                    "support_ligatures": True,
                    "support_zwj": True,
                    "shift_harakat_position": False,
                    "use_unshaped_instead_of_isolated": False,
                })
                visual = get_display(reshaper.reshape(logical), base_dir="R")
            except Exception:
                try:
                    visual = get_display(arabic_reshaper.reshape(logical), base_dir="R")
                except Exception:
                    visual = logical
            direction = "ltr"
            script = "Arab"
            language = "ar"
        else:
            visual = logical
            direction = "ltr"
            script = "Latn"
            language = "en"

        self._visual_updating = True
        try:
            self.text = visual
            for prop, value in (("base_direction", direction),
                                ("font_direction", direction),
                                ("font_script_name", script),
                                ("text_language", language)):
                if hasattr(self, prop):
                    try:
                        setattr(self, prop, value)
                    except Exception:
                        pass
            self.cursor = (len(visual), 0)
        except Exception:
            pass
        finally:
            self._visual_updating = False


    def insert_text(self, substring, from_undo=False):
        if self._visual_updating:
            return super().insert_text(substring, from_undo=from_undo)
        if substring:
            self.logical_text += str(substring)
            self._refresh_visual()

    def do_backspace(self, from_undo=False, mode="bkspc"):
        if self.logical_text:
            self.logical_text = self.logical_text[:-1]
            self._refresh_visual()

    def set_date_mode(self, enabled=True):
        self._date_visual = bool(enabled)


def _text_direction(text):
    """Choose base direction from the first *strong* character.

    Do not force a whole mixed/multiline label to RTL merely because it contains
    Arabic somewhere later. That was reversing purely English lines such as
    ``Designed by / Humaid Alnasiry`` when the next line was Arabic.
    """
    value = str(text or "")
    for ch in value:
        o = ord(ch)
        # Arabic / Hebrew and Arabic presentation forms are strong RTL.
        if ((0x0590 <= o <= 0x08FF) or (0xFB1D <= o <= 0xFDFF)
                or (0xFE70 <= o <= 0xFEFF)):
            return "rtl"
        # Latin letters are strong LTR.
        if ("A" <= ch <= "Z") or ("a" <= ch <= "z"):
            return "ltr"
    return "rtl" if ArabicTextField._has_arabic(value) else "ltr"


def make_label(text, size="16sp", color=WHITE, halign="right", bold=False, height=None, font=None):
    # النص ثابت القياس: لا يسمح للخط بتغيير حجم الحاوية أو تحريك العناصر المجاورة.
    selected_font = font or (FONT_BOLD if bold else FONT_NAME)
    direction = _text_direction(text)
    script = "Arab" if direction == "rtl" else "Latn"
    language = "ar" if direction == "rtl" else "en"
    kw = dict(text=ar(text), font_name=selected_font, font_size=size, bold=False, halign=halign,
              valign="middle", theme_text_color="Custom", text_color=color, text_size=(None, None),
              base_direction=direction, font_direction=direction, font_script_name=script, text_language=language)
    if height is not None:
        kw.update(size_hint_y=None, height=dp(height))
    label = MDLabel(**kw)
    # Constrain the texture to the actual widget width.  The previous
    # text_size=(None,height) allowed long Arabic labels to be clipped at the
    # left edge on some Android densities.
    def _sync_label_size(*_):
        try:
            label.text_size = (max(1, label.width), max(1, label.height))
        except Exception:
            pass
    label.bind(size=_sync_label_size)
    Clock.schedule_once(_sync_label_size, 0)
    return label


def make_field(multiline=False, height=52):
    field = ArabicTextField(
        hint_text="",
        font_name=FIELD_FONT_NAME,
        font_name_hint_text=FIELD_FONT_NAME,
        mode="rectangle",
        multiline=multiline,
        readonly=False,
        disabled=False,
        size_hint_y=None,
        height=dp(height),
        text_color_normal=WHITE,
        text_color_focus=WHITE,
        line_color_normal=GRAY,
        line_color_focus=GOLD,
        hint_text_color_normal=GRAY,
        hint_text_color_focus=GOLD,
        halign="right",
         padding=[dp(12), dp(8), dp(12), dp(8)],
    )
    return field


def field_group(title, field, required=False):
    """Professional field block: label sits clearly above the input border."""
    from kivy.uix.relativelayout import RelativeLayout
    field_h = field.height
    label_h = dp(28)
    gap = dp(13)
    total_h = field_h + label_h + gap
    box = RelativeLayout(size_hint_y=None, height=total_h)

    label = make_label(title + (" *" if required else ""), size="12sp",
                       color=GRAY, height=label_h, halign="right")
    label.size_hint = (1, None)
    label.height = label_h
    label.pos = (0, field_h + gap)

    field.size_hint = (1, None)
    field.height = field_h
    field.pos = (0, 0)
    box.add_widget(field)
    box.add_widget(label)
    return box


def make_toolbar(title, back=None):
    left = [["arrow-right", lambda x: back()]] if back else [["shield-check", lambda x: None]]
    bar = MDTopAppBar(title=ar(title), elevation=4, md_bg_color=NAVY_LIGHT, specific_text_color=WHITE, left_action_items=left)
    try:
        bar.ids.label_title.font_name = FONT_NAME
        bar.ids.label_title.text = ar(title)
    except Exception:
        pass
    return bar


def finish(widget):
    """Apply fonts and text direction per widget, not globally."""
    def apply(w):
        try:
            if isinstance(w, ArabicTextField):
                w.font_name = FIELD_FONT_NAME
            elif w.__class__.__name__ != "MDIcon" and hasattr(w, "font_name"):
                w.font_name = FONT_NAME
            if not isinstance(w, ArabicTextField):
                raw_text = getattr(w, "text", None)
                if raw_text is not None:
                    direction = _text_direction(raw_text)
                    script = "Arab" if direction == "rtl" else "Latn"
                    language = "ar" if direction == "rtl" else "en"
                    for prop, value in (("base_direction", direction), ("font_direction", direction),
                                        ("font_script_name", script), ("text_language", language)):
                        if hasattr(w, prop):
                            try:
                                setattr(w, prop, value)
                            except Exception:
                                pass
        except Exception:
            pass
        for c in list(getattr(w, "children", [])):
            apply(c)
    Clock.schedule_once(lambda dt: apply(widget), 0)
    Clock.schedule_once(lambda dt: apply(widget), .15)

def popup(title, message, buttons=None, height=240):
    box = MDBoxLayout(orientation="vertical", padding=dp(14), spacing=dp(10))
    msg = make_label(message, size="14sp", height=145)
    msg.font_name = FONT_NAME
    msg.text = ar(message)
    box.add_widget(msg)
    p = Popup(title=ar(title), content=box, size_hint=(.92, None), height=dp(height), auto_dismiss=False)
    # بعض إصدارات KivyMD قد تعيد بناء عنوان/محتوى Popup بعد الفتح؛
    # إعادة فرض الخط تمنع ظهور مربعات □□□ في الرسائل العربية.
    row = MDBoxLayout(orientation="horizontal", spacing=dp(6), size_hint_y=None, height=dp(48))
    buttons = buttons or [("حسنًا", None, GOLD, NAVY)]
    for text, cb, bg, tc in buttons:
        b = MDRaisedButton(text=ar(text), font_name=FONT_NAME, md_bg_color=bg, theme_text_color="Custom", text_color=tc)
        b.bind(on_release=lambda x, cb=cb: (p.dismiss(), cb() if cb else None))
        row.add_widget(b)
    box.add_widget(row)
    p.open()
    return p


def now_string():
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def make_id():
    return datetime.now().strftime("%Y%m%d%H%M%S%f")


def migrate_records():
    records = load_records(); changed = False
    for r in records:
        if not r.get("registration_date") and r.get("hijri_date"):
            r["registration_date"] = r.get("hijri_date")
            r["registration_date_key"] = "-".join(f"{x:02d}" for x in hijri_key(r["registration_date"]))
            changed = True
        if r.get("injury_date") and "-" in str(r["injury_date"]):
            # التاريخ الميلادي القديم لا يمكن تحويله هنا بثقة؛ لا نضع تاريخًا مخترعًا.
            pass
    if changed:
        save_records(records)
    return records


# ============================================================
# تنظيم واجهة المستخدم — أقسام قابلة للطي
# ============================================================
def ui_section(title, children, initially_open=True):
    wrapper=MDBoxLayout(orientation="vertical",spacing=dp(3),size_hint_y=None)
    header=MDRectangleFlatButton(
        text=ar(("▾ " if initially_open else "▸ ")+title),
        font_name=FONT_NAME,theme_text_color="Custom",text_color=GOLD,
        size_hint_y=None,height=dp(44),halign="right"
    )
    body=MDBoxLayout(orientation="vertical",spacing=dp(6),size_hint_y=None)
    body.bind(minimum_height=body.setter("height"))
    for child in children: body.add_widget(child)
    state={"open":bool(initially_open)}
    def apply_state(*_):
        body.height=body.minimum_height if state["open"] else 0
        body.opacity=1 if state["open"] else 0
        body.disabled=not state["open"]
        header.text=ar(("▾ " if state["open"] else "▸ ")+title)
        wrapper.height=header.height+body.height+dp(3)
    def toggle(*_):
        state["open"]=not state["open"];apply_state()
    header.bind(on_release=toggle)
    wrapper.add_widget(header);wrapper.add_widget(body)
    Clock.schedule_once(apply_state,0)
    return wrapper


