class HijriPickerPopup(Popup):
    def __init__(self, field, title="اختيار التاريخ الهجري", initial=None, allow_empty=False, **kwargs):
        self.target_field = field
        self.allow_empty = allow_empty
        y, m, d = hijri_today()
        if initial:
            try:
                dd, mm, yy = str(initial).split("/", 2)
                y, m, d = int(yy), HIJRI_MONTHS.index(mm) + 1, int(dd)
            except Exception:
                pass
        box = MDBoxLayout(orientation="vertical", padding=dp(14), spacing=dp(10))
        box.add_widget(make_label("التاريخ الهجري", size="20sp", bold=True, halign="center", height=38))
        row = MDBoxLayout(orientation="horizontal", spacing=dp(6), size_hint_y=None, height=dp(58))
        self.day = arabic_spinner(text=str(d), values=tuple(str(i) for i in range(1, 31)), size_hint_x=.22)
        month_display = tuple(ar(x) for x in HIJRI_MONTHS)
        self.month = arabic_spinner(text=ar(HIJRI_MONTHS[m-1]), values=month_display, size_hint_x=.48)
        self.year = arabic_spinner(text=str(y), values=tuple(str(i) for i in range(1350, 1501)), size_hint_x=.30)
        for sp in (self.day, self.month, self.year):
            sp.font_name = FONT_NAME
        row.add_widget(self.day); row.add_widget(self.month); row.add_widget(self.year); box.add_widget(row)
        box.add_widget(make_label("اختر اليوم والشهر والسنة ثم اضغط حفظ.", size="11sp", color=GRAY, halign="center", height=28))
        buttons = MDBoxLayout(orientation="horizontal", spacing=dp(8), size_hint_y=None, height=dp(50))
        if allow_empty:
            clear = MDRectangleFlatButton(text=ar("مسح"), font_name=FONT_NAME, theme_text_color="Custom", text_color=RED)
            clear.bind(on_release=lambda x: (field.set_logical_text(""), self.dismiss()))
            buttons.add_widget(clear)
        save = MDRaisedButton(text=ar("حفظ"), font_name=FONT_NAME, md_bg_color=GOLD, theme_text_color="Custom", text_color=NAVY)
        cancel = MDFlatButton(text=ar("إلغاء"), font_name=FONT_NAME, theme_text_color="Custom", text_color=GRAY)
        save.bind(on_release=self.accept_date); cancel.bind(on_release=lambda x: self.dismiss())
        buttons.add_widget(save); buttons.add_widget(cancel); box.add_widget(buttons)
        super().__init__(title=ar(title), content=box, size_hint=(.95, .44), auto_dismiss=False, **kwargs)

    def accept_date(self, *args):
        try:
            y = int(self.year.text); m = next(i for i,v in enumerate(HIJRI_MONTHS, 1) if ar(v) == self.month.text); d = min(int(self.day.text), days_in_hijri_month(y, m))
            self.target_field.set_logical_text(hijri_text(y, m, d))
        finally:
            self.dismiss()


def attach_date_picker(field, allow_empty=False):
    field.readonly = True
    field.bind(on_touch_down=lambda instance, touch: open_date(instance, touch, allow_empty))


def open_date(field, touch, allow_empty=False):
    if field.collide_point(*touch.pos):
        Clock.schedule_once(lambda dt: HijriPickerPopup(field, initial=field.get_logical_text(), allow_empty=allow_empty).open(), 0)
        return True
    return False


def add_date_button(parent, field, allow_empty=False):
    b = MDRectangleFlatButton(text=ar("فتح عداد التاريخ"), font_name=FONT_NAME, theme_text_color="Custom", text_color=GOLD, size_hint_y=None, height=dp(38))
    b.bind(on_release=lambda x: HijriPickerPopup(field, initial=field.get_logical_text(), allow_empty=allow_empty).open())
    parent.add_widget(b)


