def next_report_number(settings):
    rpt = settings["report"]
    counter = int(rpt.get("report_counter", 0) or 0) + 1
    rpt["report_counter"] = counter
    save_json(SETTINGS_FILE, settings)
    y = hijri_today()[0]
    return f"{rpt.get('report_number_prefix','ALB')}-{counter:04d}/{y}"


def backup_package(work_copy=False):
    """إنشاء نسخة احتياطية أو نسخة عمل قابلة للنقل.

    نسخة العمل تحتوي على Manifest يحدد المركز وعدد السجلات، وتبقى متوافقة
    مع النسخ القديمة لأن data.json/settings.json يظلان في الجذر.
    """
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    ext = ".albwork" if work_copy else ".albbackup"
    prefix = "ALBADR_WORK" if work_copy else "ALBADR_BACKUP"
    path = os.path.join(BACKUPS_DIR, f"{prefix}_{stamp}{ext}")
    settings = get_settings()
    records = load_json(DATA_FILE, [])
    profile = settings.get("center_profile", {}) if isinstance(settings, dict) else {}
    manifest = {
        "format": "ALBADR_WORK" if work_copy else "ALBADR_BACKUP",
        "version": 1,
        "created_at": datetime.now().isoformat(timespec="seconds"),
        "center_id": str(profile.get("center_id", "") or ""),
        "center_name": str(profile.get("center_name", "") or ""),
        "center_code": str(profile.get("center_code", "") or ""),
        "record_count": len(records) if isinstance(records, list) else 0,
    }
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
        if os.path.isfile(DATA_FILE): z.write(DATA_FILE, "data.json")
        if os.path.isfile(SETTINGS_FILE): z.write(SETTINGS_FILE, "settings.json")
        z.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2))
        if os.path.isdir(ASSETS_DIR):
            for root, _, files in os.walk(ASSETS_DIR):
                for f in files:
                    fp = os.path.join(root, f); z.write(fp, os.path.relpath(fp, BASE_DIR))
    return path


def create_work_copy():
    return backup_package(work_copy=True)

def validate_backup(path):
    try:
        with zipfile.ZipFile(path, "r") as z:
            names = set(z.namelist())
            if "data.json" not in names or "settings.json" not in names:
                return False, "النسخة لا تحتوي على ملفات البيانات والإعدادات المطلوبة."
            data = json.loads(z.read("data.json").decode("utf-8"))
            settings = json.loads(z.read("settings.json").decode("utf-8"))
            if not isinstance(data, list) or not isinstance(settings, dict):
                return False, "بنية النسخة الاحتياطية غير صحيحة."
        return True, ""
    except Exception as exc:
        return False, str(exc)


def restore_package(path):
    ok, msg = validate_backup(path)
    if not ok:
        raise RuntimeError(msg)
    with zipfile.ZipFile(path, "r") as z:
        z.extract("data.json", BACKUPS_DIR)
        z.extract("settings.json", BACKUPS_DIR)
        for name in z.namelist():
            if name.startswith("report_assets/") and not name.endswith("/"):
                z.extract(name, BASE_DIR)
    shutil.copy2(os.path.join(BACKUPS_DIR, "data.json"), DATA_FILE)
    shutil.copy2(os.path.join(BACKUPS_DIR, "settings.json"), SETTINGS_FILE)
    os.remove(os.path.join(BACKUPS_DIR, "data.json")); os.remove(os.path.join(BACKUPS_DIR, "settings.json"))


def copy_asset_to_app(path, prefix):
    if not path or not os.path.isfile(path):
        return ""
    ext = os.path.splitext(path)[1].lower() or ".png"
    dst = os.path.join(ASSETS_DIR, prefix + ext)
    try:
        shutil.copy2(path, dst)
        return dst
    except Exception:
        return path


def _allow_file_uri_android():
    try:
        from jnius import autoclass
        StrictMode = autoclass("android.os.StrictMode")
        Builder = autoclass("android.os.StrictMode$VmPolicy$Builder")
        StrictMode.setVmPolicy(Builder().build())
    except Exception:
        pass

def _android_file_uri(path):
    from jnius import autoclass
    File = autoclass("java.io.File")
    Uri = autoclass("android.net.Uri")
    return Uri.fromFile(File(os.path.abspath(path)))

def _public_report_copy(path):
    """ضع نسخة ثابتة من التقرير في Download/ALBADR Reports."""
    if not path or not os.path.isfile(path):
        raise FileNotFoundError("الملف غير موجود")
    try:
        os.makedirs(PUBLIC_REPORTS_DIR, exist_ok=True)
        target = os.path.join(PUBLIC_REPORTS_DIR, os.path.basename(path))
        if os.path.abspath(path) != os.path.abspath(target):
            shutil.copy2(path, target)
        return target
    except Exception:
        return path

def _android_content_uri(path):
    """إنشاء URI دائم وقابل للفتح/المشاركة عبر MediaStore على Android 10+."""
    from jnius import autoclass
    PythonActivity = autoclass("org.kivy.android.PythonActivity")
    MediaStore = autoclass("android.provider.MediaStore")
    ContentValues = autoclass("android.content.ContentValues")
    activity = PythonActivity.mActivity
    resolver = activity.getContentResolver()
    try:
        collection = MediaStore.Downloads.EXTERNAL_CONTENT_URI
    except Exception:
        return None

    filename = os.path.basename(path)
    mime = mimetypes.guess_type(path)[0] or "application/octet-stream"

    # Avoid creating a second MediaStore entry every time the user presses
    # Open/Share. Reuse an existing public copy when one is already indexed.
    existing = None
    cursor = None
    try:
        projection = [MediaStore.MediaColumns._ID, MediaStore.MediaColumns.DISPLAY_NAME]
        cursor = resolver.query(collection, projection,
                                MediaStore.MediaColumns.DISPLAY_NAME + "=?",
                                [filename], None)
        if cursor is not None and cursor.moveToFirst():
            idx = cursor.getColumnIndex(MediaStore.MediaColumns._ID)
            if idx >= 0:
                row_id = cursor.getLong(idx)
                existing = collection.buildUpon().appendPath(str(row_id)).build()
    except Exception as exc:
        print("MEDIASTORE QUERY", exc)
    finally:
        try:
            if cursor is not None:
                cursor.close()
        except Exception:
            pass

    # If an existing entry is found, refresh its bytes by opening its stream.
    if existing is not None:
        try:
            out = resolver.openOutputStream(existing, "wt")
            if out is not None:
                with open(path, "rb") as inp:
                    while True:
                        chunk = inp.read(1024 * 1024)
                        if not chunk:
                            break
                        out.write(chunk)
                out.close()
                return existing
        except Exception as exc:
            print("MEDIASTORE REFRESH", exc)

    values = ContentValues()
    values.put(MediaStore.MediaColumns.DISPLAY_NAME, filename)
    values.put(MediaStore.MediaColumns.MIME_TYPE, mime)
    try:
        values.put(MediaStore.MediaColumns.RELATIVE_PATH, "Download/ALBADR Reports")
        # Pending prevents Android's media/indexing layer from exposing a
        # half-written document to WPS/Files. It is cleared only after the
        # entire file has been copied successfully.
        values.put(MediaStore.MediaColumns.IS_PENDING, 1)
    except Exception:
        pass

    uri = resolver.insert(collection, values)
    if uri is None:
        return None
    try:
        out = resolver.openOutputStream(uri, "w")
        if out is None:
            raise IOError("تعذر فتح مسار الكتابة في MediaStore")
        with open(path, "rb") as inp:
            while True:
                chunk = inp.read(1024 * 1024)
                if not chunk:
                    break
                out.write(chunk)
        out.close()
        try:
            done = ContentValues()
            done.put(MediaStore.MediaColumns.IS_PENDING, 0)
            resolver.update(uri, done, None, None)
        except Exception as exc:
            print("MEDIASTORE PUBLISH", exc)
        return uri
    except Exception as exc:
        print("MEDIASTORE WRITE", exc)
        try:
            resolver.delete(uri, None, None)
        except Exception:
            pass
        return None

def _get_share_uri(path):
    public_path = _public_report_copy(path)
    try:
        uri = _android_content_uri(public_path)
        if uri is not None:
            return uri
    except Exception as exc:
        print("MEDIASTORE", exc)
    _allow_file_uri_android()
    return _android_file_uri(public_path)

def open_file(path):
    try:
        if not path or not os.path.isfile(path):
            raise FileNotFoundError("الملف غير موجود")
        from jnius import autoclass
        PythonActivity = autoclass("org.kivy.android.PythonActivity")
        Intent = autoclass("android.content.Intent")
        activity = PythonActivity.mActivity
        uri = _get_share_uri(path)
        intent = Intent(Intent.ACTION_VIEW)
        ClipData = autoclass("android.content.ClipData")
        mime = mimetypes.guess_type(path)[0] or "*/*"
        intent.setDataAndType(uri, mime)
        intent.setClipData(ClipData.newRawUri("ALBADR", uri))
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        activity.startActivity(intent)
        return True
    except Exception as exc:
        print("OPEN", exc)
        popup("تعذر فتح الملف", str(exc), height=250)
        return False

def share_file(path):
    try:
        if not path or not os.path.isfile(path):
            raise FileNotFoundError("الملف غير موجود")
        from jnius import autoclass
        PythonActivity = autoclass("org.kivy.android.PythonActivity")
        Intent = autoclass("android.content.Intent")
        ClipData = autoclass("android.content.ClipData")
        activity = PythonActivity.mActivity
        uri = _get_share_uri(path)
        mime = mimetypes.guess_type(path)[0] or "application/octet-stream"
        intent = Intent(Intent.ACTION_SEND)
        intent.setType(mime)
        # بعض إصدارات PyJNIus تختار overload الخاص بـ String إذا استُخدم putExtra مباشرة.
        # نضع URI في ClipData دائمًا، ونجرب EXTRA_STREAM كإضافة اختيارية.
        intent.setClipData(ClipData.newRawUri("ALBADR", uri))
        try:
            intent.putExtra(Intent.EXTRA_STREAM, uri)
        except Exception as extra_exc:
            print("EXTRA_STREAM", extra_exc)
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
        # PyJNIus can select the wrong createChooser overload when a
        # java.lang.String wrapper is supplied explicitly. Passing Java null
        # selects the platform-compatible CharSequence overload on Android
        # versions used by Pydroid, while the share sheet still opens normally.
        chooser = Intent.createChooser(intent, None)
        activity.startActivity(chooser)
        return True
    except Exception as exc:
        print("SHARE", exc)
        popup("المشاركة", "تعذر فتح نافذة المشاركة.\n" + str(exc), height=280)
        return False


