def report_fields(settings):
    fields = [f for f in settings["fields"] if f.get("enabled", True) and f.get("key") != "registration_date"]
    selected = settings["report"].get("selected_fields", [])
    if not selected:
        return fields
    by = {f["key"]: f for f in fields}
    return [by[k] for k in selected if k in by]


def matches_records(record, filters):
    text = str(filters.get("text", "")).strip().lower()
    if text:
        blob = " ".join(str(v) for v in record.values()).lower()
        if text not in blob:
            return False
    df = str(filters.get("date_from", "")).strip()
    dt = str(filters.get("date_to", "")).strip()
    rk = hijri_key(record.get("registration_date", record.get("hijri_date", "")))
    if df and rk < hijri_key(df): return False
    if dt and rk > hijri_key(dt): return False
    key = filters.get("filter_key")
    value = str(filters.get("filter_value", "")).strip().lower()
    if key and value and value not in str(record.get(key, "")).lower(): return False
    return True


def filter_records(records, filters):
    return [r for r in records if matches_records(r, filters)]


def report_value(record, cfg):
    return "" if record.get(cfg["key"]) is None else str(record.get(cfg["key"], ""))


