def _hex_color(value, default="FFFFFF"):
    try:
        value=str(value or default).replace("#","")
        if len(value)!=6: value=default
        return tuple(int(value[i:i+2],16)/255 for i in (0,2,4))
    except Exception: return (1,1,1)

def _report_text(value):
    """Normalize report text before sending it to ReportLab.

    Older editor builds could store Kivy/markup text such as ``<para>...``
    and literal ``\\ufe..`` escapes.  ReportLab treats those as XML markup and
    can raise ``ParaFrag._selfClosingTag``.  This function converts the old
    representations to safe ReportLab markup while keeping basic formatting.
    """
    if value is None:
        return ""
    text = str(value)
    # Decode literal unicode escapes without changing ordinary backslashes.
    def _u(m):
        try:
            return chr(int(m.group(1), 16))
        except Exception:
            return m.group(0)
    text = re.sub(r"\\u([0-9a-fA-F]{4})", _u, text)
    text = re.sub(r"\\U([0-9a-fA-F]{8})", _u, text)
    # Remove legacy paragraph wrappers and convert line breaks.
    text = re.sub(r"</?para(?:\s+[^>]*)?>", "", text, flags=re.I)
    text = re.sub(r"</?br\s*/?>", "\n", text, flags=re.I)
    # Convert common Kivy markup to ReportLab markup.
    text = re.sub(r"\[b\]", "<b>", text, flags=re.I)
    text = re.sub(r"\[/b\]", "</b>", text, flags=re.I)
    text = re.sub(r"\[u\]", "<u>", text, flags=re.I)
    text = re.sub(r"\[/u\]", "</u>", text, flags=re.I)
    text = re.sub(r"\[i\]", "<i>", text, flags=re.I)
    text = re.sub(r"\[/i\]", "</i>", text, flags=re.I)
    text = re.sub(r"\[color=(#[0-9a-fA-F]{6})\]", r'<font color="\1">', text, flags=re.I)
    text = re.sub(r"\[/color\]", "</font>", text, flags=re.I)
    # Escape unsafe XML characters but preserve only the markup we just created.
    tokens = re.split(r"(<(?:b|/b|u|/u|i|/i|font(?:\s+color=\"#[0-9a-fA-F]{6}\")?|/font)>)", text)
    out=[]
    for token in tokens:
        if token.startswith("<") and token.endswith(">"):
            out.append(token)
        else:
            out.append(html.escape(token, quote=False))
    return "".join(out).replace("\n", "<br/>")


REPORT_FORCE_BOLD = False

def _report_para(value, style):
    """Create a ReportLab paragraph using ONE Arabic shaping pipeline.

    IMPORTANT for the Android/Pydroid build used by ALBADR:
    ReportLab may accept ``wordWrap=RTL`` even when its HarfBuzz shaper is
    unavailable. In that situation the paragraph is syntactically valid but
    Arabic glyphs are emitted as isolated/unjoined characters. The previous
    implementation therefore *succeeded* in the native branch and never
    reached the working arabic_reshaper/python-bidi fallback.

    For Arabic/mixed text we now explicitly shape once with
    arabic_reshaper + python-bidi and then tell ReportLab to lay out the
    already-shaped visual string as LTR. For non-Arabic text we keep the
    normal ReportLab path. Presentation-form input from older editor builds
    is normalized back to logical Unicode first, preventing double shaping.
    """
    from reportlab.platypus import Paragraph
    import unicodedata

    safe = _report_text(value)
    if REPORT_FORCE_BOLD and safe.strip() and not (safe.strip().startswith("<b>") and safe.strip().endswith("</b>")):
        safe = f"<b>{safe}</b>"
    plain = re.sub(r"<[^>]+>", "", safe)
    direction = _text_direction(plain)

    # Always use the explicit Arabic pipeline on Android for Arabic text.
    # NFKC converts legacy Arabic Presentation Forms back to normal Unicode
    # so copied/old editor content is never reshaped twice.
    if direction == "rtl":
        chunks = re.split(r"(<[^>]+>)", safe)
        shaped = []
        for chunk in chunks:
            if chunk.startswith("<") and chunk.endswith(">"):
                shaped.append(chunk)
                continue
            try:
                logical = unicodedata.normalize("NFKC", chunk)
                shaped.append(report_ar(logical))
            except Exception:
                shaped.append(chunk)
        try:
            rtl_style = style.clone(f"{style.name}_ar_shaped")
        except Exception:
            rtl_style = style
        # The bidi function has already produced visual order. Do not ask
        # ReportLab for a second RTL reordering.
        try:
            rtl_style.wordWrap = "LTR"
        except Exception:
            pass
        return Paragraph("".join(shaped), rtl_style)

    try:
        ltr_style = style.clone(f"{style.name}_ltr")
        ltr_style.wordWrap = "LTR"
    except Exception:
        ltr_style = style
    return Paragraph(safe, ltr_style)


def export_pdf(records, settings, stamp=None):
    """Create the ALBADR report in the requested two-part layout.

    Page 1 is always an independent A4 portrait cover.  Data pages start on
    page 2 and use their own portrait/landscape orientation.  The same
    editable header/footer is rendered on every page and is positioned from
    the current page dimensions, so it never remains stuck to portrait
    coordinates when the table pages are landscape.
    """
    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4, portrait, landscape
        from reportlab.platypus import BaseDocTemplate, PageTemplate, Frame, Paragraph, Spacer, Table, TableStyle, PageBreak, NextPageTemplate, Image as RLImage, KeepTogether
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        from reportlab.lib.enums import TA_RIGHT, TA_CENTER
    except ImportError as exc:
        raise RuntimeError("ReportLab غير مثبت. ثبّت reportlab ثم أعد المحاولة.") from exc

    stamp = stamp or datetime.now().strftime("%Y%m%d_%H%M%S")
    rpt = settings["report"]
    global REPORT_FORCE_BOLD
    REPORT_FORCE_BOLD = bool(rpt.get("report_bold", False))
    number = next_report_number(settings) if rpt.get("auto_report_number", True) else ""
    font = "ALBADR_PDF"
    try:
        pdfmetrics.getFont(font)
    except Exception:
        if PDF_FONT_FILE and os.path.isfile(PDF_FONT_FILE):
            pdfmetrics.registerFont(TTFont(font, PDF_FONT_FILE))
        else:
            font = "Helvetica"

    first_size = portrait(A4)
    data_size = landscape(A4) if rpt.get("data_orientation", rpt.get("table_orientation", "landscape")) == "landscape" else portrait(A4)
    cover_visible = bool(rpt.get("cover_visible", True))
    path = os.path.join(REPORTS_DIR, f"ALBADR_REPORT_{stamp}.pdf")
    margin = float(rpt.get("margins_mm", 8)) * 2.83465

    def col(value, default="FFFFFF"):
        return colors.Color(*_hex_color(value, default))

    header_line = col(rpt.get("header_line_color", "D8B24A"), "D8B24A")
    header_text = col(rpt.get("header_text_color", "111111"), "111111")
    footer_text = col(rpt.get("footer_text_color", "111111"), "111111")
    table_head = col(rpt.get("table_header_color", "BFE7F5"), "BFE7F5")
    table_text = col(rpt.get("table_text_color", "111111"), "111111")

    def fmt_line(v):
        v = str(v or "")
        return (v.replace("{number}", str(number))
                 .replace("{hijri_today}", hijri_text(*hijri_today()))
                 .replace("{gregorian_today}", datetime.now().strftime("%Y-%m-%d"))
                 .replace("{today}", hijri_text(*hijri_today()))
                 .replace("{page}", "{page}"))

    def _lines(key, fallback_key=None, limit=None):
        vals = rpt.get(key, [])
        if not isinstance(vals, list):
            vals = []
        if not vals and fallback_key:
            vals = [rpt.get(fallback_key, "")]
        vals = [str(x) for x in vals if str(x).strip()]
        return vals[:limit] if limit else vals

    def _header_height(is_data_page):
        fs = float(rpt.get("header_font_size", 11))
        left_n = max(1, len(_lines("left_lines")))
        center_n = max(1, len(_lines("center_lines")))
        right_n = max(1, len(_lines("right_lines")))
        rows = max(left_n, center_n, right_n)
        logo_extra = 0
        logo_path = rpt.get("logo_path", "")
        if logo_path and os.path.isfile(logo_path) and rpt.get("header_logo_visible", True):
            logo_extra = 50 if is_data_page else 64
        org_extra = (fs + 7) if str(rpt.get("organization_name", "")).strip() else 0
        return max((64 if is_data_page else 78), rows * (fs + 4) + logo_extra + org_extra + 14)

    def _footer_height():
        fs = float(rpt.get("footer_font_size", 9))
        return max(38, 2 * (fs + 4) + (14 if rpt.get("page_numbers", True) else 4))

    def draw_header_footer(canvas, doc):
        canvas.saveState()
        w, h = canvas._pagesize
        top = h - margin
        line_y = top

        # -------- Header: 3 flexible columns, unlimited rows --------
        if rpt.get("header_visible", True):
            is_data_page = (doc.page > 1 and data_size[0] > data_size[1])
            fs = float(rpt.get("header_font_size", 11))
            header_h = _header_height(is_data_page)
            line_y = top - header_h - 4
            st_left = ParagraphStyle("hdrL", fontName=font, fontSize=float(rpt.get("header_left_size", fs)), leading=fs+3, alignment=TA_RIGHT, textColor=header_text)
            st_center = ParagraphStyle("hdrC", fontName=font, fontSize=float(rpt.get("header_center_size", fs)), leading=fs+3, alignment=TA_CENTER, textColor=header_text)
            st_right = ParagraphStyle("hdrR", fontName=font, fontSize=float(rpt.get("header_right_size", fs)), leading=fs+3, alignment=TA_RIGHT, textColor=header_text)
            left_lines = _lines("left_lines")
            center_lines = _lines("center_lines")
            right_lines = _lines("right_lines")
            left = "<br/>".join(_report_text(fmt_line(x)) for x in left_lines)
            center = "<br/>".join(_report_text(fmt_line(x)) for x in center_lines)
            right = "<br/>".join(_report_text(fmt_line(x)) for x in right_lines)
            # إزاحة بسيطة إلى الشمال مع الحفاظ على حدود الصفحة؛ قابلة للضبط من الإعدادات.
            shift = (w - 2*margin) * float(rpt.get("header_shift_percent", -3.3)) / 100.0
            content_w = (w - 2*margin) * 0.94
            col_w = [content_w*.31, content_w*.38, content_w*.31]
            head = Table([[_report_para(left, st_left), _report_para(center, st_center), _report_para(right, st_right)]],
                         colWidths=col_w, rowHeights=[header_h])
            left_inset = col_w[0] * max(0, float(rpt.get("header_left_inset_percent", 5.0))) / 100.0
            head.setStyle(TableStyle([
                ("VALIGN", (0,0), (-1,-1), "TOP"),
                ("ALIGN", (0,0), (0,0), "RIGHT"), ("ALIGN", (1,0), (1,0), "CENTER"), ("ALIGN", (2,0), (2,0), "RIGHT"),
                # العمود الشمالي (الأيسر) مزاح للداخل قليلًا ليتوازن بصريًا.
                ("LEFTPADDING", (0,0), (0,0), left_inset + 2), ("RIGHTPADDING", (0,0), (0,0), 2),
                ("LEFTPADDING", (1,0), (-1,-1), 2), ("RIGHTPADDING", (1,0), (-1,-1), 2),
                ("TOPPADDING", (0,0), (-1,-1), 0), ("BOTTOMPADDING", (0,0), (-1,-1), 0),
            ]))
            base_x = margin + ((w - 2*margin) - content_w)/2.0
            draw_x = max(margin, min(w-margin-content_w, base_x + shift))
            head.wrapOn(canvas, content_w, header_h)
            head.drawOn(canvas, draw_x, top-header_h)
            logo_path = rpt.get("logo_path", "")
            if logo_path and os.path.isfile(logo_path) and rpt.get("header_logo_visible", True):
                try:
                    logo_w = min(88, w*.12) if not is_data_page else min(72, w*.09)
                    logo_h = min(58, w*.085) if not is_data_page else min(44, w*.055)
                    # مباشرة تحت البسملة/نص الوسط: نحسب بداية الشعار من عدد أسطر الوسط.
                    center_text_h = max(1, len(center_lines)) * (float(rpt.get("header_center_size", fs)) + 3)
                    logo_y = top - center_text_h - logo_h - 3
                    logo_y = max(line_y + 5, logo_y)
                    canvas.drawImage(logo_path, w/2-logo_w/2 + shift, logo_y, width=logo_w, height=logo_h, preserveAspectRatio=True, mask="auto")
                except Exception:
                    pass
            # اسم الجهة يظهر مباشرة تحت الشعار وقبل الخط الفاصل.
            org_name = str(rpt.get("organization_name", "") or "").strip()
            if org_name:
                try:
                    org_style = ParagraphStyle("headerOrganization", fontName=font, fontSize=max(8, fs-1),
                                               leading=max(11, fs+1), alignment=TA_CENTER, textColor=header_text)
                    op = _report_para(org_name, org_style)
                    ow, oh = op.wrap(content_w*.55, max(18, fs+8))
                    org_y = line_y + 3
                    # في حالة وجود الشعار يبقى الاسم تحته، وإلا يبقى فوق الفاصل مباشرة.
                    if logo_path and os.path.isfile(logo_path) and rpt.get("header_logo_visible", True):
                        org_y = max(line_y + 3, logo_y - oh - 2)
                    op.drawOn(canvas, w/2-ow/2 + shift, org_y)
                except Exception:
                    pass
            canvas.setStrokeColor(header_line)
            canvas.setLineWidth(1.2)
            canvas.line(margin, line_y, w-margin, line_y)

        # -------- Cover page body: drawn directly on page 1 so it can NEVER spill to page 2 --------
        if cover_visible and doc.page == 1:
            cover_title_style = ParagraphStyle("coverTitleCanvas", fontName=font, fontSize=float(rpt.get("cover_title_size",18)),
                                               leading=float(rpt.get("cover_title_size",18))+4, alignment=TA_CENTER,
                                               textColor=col(rpt.get("cover_text_color","111111")))
            cover_text_style = ParagraphStyle("coverTextCanvas", fontName=font, fontSize=float(rpt.get("cover_text_size",13)),
                                              leading=float(rpt.get("cover_text_size",13))+5, alignment=TA_CENTER,
                                              textColor=col(rpt.get("cover_text_color","111111")))
            title_y = line_y - 14
            title_w = w - 2*margin - 8
            title_para = _report_para(fmt_line(rpt.get("cover_title", rpt.get("title", "تقرير"))), cover_title_style)
            _, title_h = title_para.wrap(title_w-14, 70)
            title_h=max(32,min(52,title_h+12))
            canvas.setStrokeColor(colors.black); canvas.setLineWidth(1.3)
            canvas.rect(margin+4, title_y-title_h, title_w, title_h, stroke=1, fill=0)
            title_para.wrapOn(canvas,title_w-14,title_h-8); title_para.drawOn(canvas,margin+11,title_y-title_h+5)

            rows = rpt.get("cover_rows", []) or []
            if not rows:
                rows = [x for x in str(rpt.get("cover_body", "") or "").splitlines() if x.strip()]
            rows = [str(x) for x in rows if str(x).strip()][:12]
            pos=float(rpt.get("cover_position", .5) or .5)
            content_top = title_y-title_h-18 - (pos-.5)*70
            available_h = (h-margin-230) - (margin+75)
            row_h = min(38, max(22, available_h/max(1,len(rows)+2)))
            y = content_top
            for idx,row in enumerate(rows):
                style=cover_text_style
                # Preserve the approved visual hierarchy: first rows are salutations, later rows can be body text.
                if idx == 0:
                    style=ParagraphStyle(f"coverR{idx}",parent=cover_text_style,fontSize=max(11,float(rpt.get("cover_text_size",13))-1),leading=18,textColor=col(rpt.get("cover_text_color","111111")))
                p=_report_para(fmt_line(row),style); pw,ph=p.wrap(w-2*margin-20,row_h+18)
                if ph>row_h+18:
                    ph=row_h+18
                p.drawOn(canvas,margin+10,y-ph)
                y-=row_h

            # Count is intentionally red, matching the supplied model.
            count_style=ParagraphStyle("coverCountCanvas",parent=cover_text_style,fontSize=13,leading=18,textColor=colors.red)
            cp=_report_para(f"عدد السجلات: {len(records)}",count_style); cw,ch=cp.wrap(w-2*margin-20,30); cp.drawOn(canvas,margin+10,y-ch); y-=row_h

        # -------- Footer: 3 columns × 2 flexible rows --------
        if rpt.get("footer_visible", True):
            footer_h = _footer_height()
            y0 = margin + 2
            line_y_footer = y0 + footer_h
            canvas.setStrokeColor(header_line); canvas.setLineWidth(.7); canvas.line(margin, line_y_footer, w-margin, line_y_footer)
            footer_fs = float(rpt.get("footer_font_size", 9))
            footer_style = ParagraphStyle("footerNativeRTL", fontName=font, fontSize=footer_fs,
                                          leading=footer_fs+3, alignment=TA_RIGHT, textColor=footer_text)
            footer_center_style = ParagraphStyle("footerNativeCenter", fontName=font, fontSize=footer_fs,
                                                 leading=footer_fs+3, alignment=TA_CENTER, textColor=footer_text)
            cols = [
                (_lines("footer_left_lines", "footer_left", 2), footer_style),
                (_lines("footer_center_lines", "footer_center", 2), footer_center_style),
                (_lines("footer_right_lines", "footer_right", 2), footer_style),
            ]
            col_w = (w-2*margin)/3.0
            row_h = footer_fs + 4
            for ci, (vals, st) in enumerate(cols):
                x = margin + ci*col_w
                for ri in range(2):
                    txt = fmt_line(vals[ri]) if ri < len(vals) else ""
                    if txt.strip():
                        fp = _report_para(txt, st)
                        _, ph = fp.wrap(col_w-6, row_h+4)
                        fp.drawOn(canvas, x+3, y0 + (1-ri)*row_h + max(0, (row_h-ph)/2))
            if rpt.get("page_numbers", True):
                pp = _report_para(f"صفحة {doc.page}", footer_center_style)
                _, ph = pp.wrap(col_w-6, footer_fs+5)
                pp.drawOn(canvas, margin+col_w+3, max(y0-2, y0-ph-1))
        canvas.restoreState()

    # مساحة ديناميكية: إضافة أي صف في الترويسة/التذييل تحرك المحتوى والخطوط تلقائيًا.
    cover_top_reserved = (_header_height(False) + 22) if rpt.get("header_visible", True) else 20
    data_top_reserved = (_header_height(True) + 18) if rpt.get("header_visible", True) else 16
    bottom_reserved = (_footer_height() + 8) if rpt.get("footer_visible", True) else 15
    cover_frame = Frame(margin, margin+bottom_reserved, first_size[0]-2*margin,
                        first_size[1]-2*margin-cover_top_reserved-bottom_reserved,
                        id="cover", leftPadding=4, rightPadding=4, topPadding=4, bottomPadding=4)
    data_frame = Frame(margin, margin+bottom_reserved, data_size[0]-2*margin,
                       data_size[1]-2*margin-data_top_reserved-bottom_reserved,
                       id="data", leftPadding=2, rightPadding=2, topPadding=2, bottomPadding=2)

    doc = BaseDocTemplate(path, pagesize=(first_size if cover_visible else data_size),
                          leftMargin=margin, rightMargin=margin, topMargin=margin, bottomMargin=margin,
                          title=str(rpt.get("title", "ALBADR")))
    if cover_visible:
        doc.addPageTemplates([
            PageTemplate(id="COVER", pagesize=first_size, frames=[cover_frame], onPage=draw_header_footer),
            PageTemplate(id="DATA", pagesize=data_size, frames=[data_frame], onPage=draw_header_footer),
        ])
    else:
        doc.addPageTemplates([PageTemplate(id="DATA", pagesize=data_size, frames=[data_frame], onPage=draw_header_footer)])

    cover_title = ParagraphStyle("coverTitle", fontName=font, fontSize=float(rpt.get("cover_title_size", 18)),
                                 leading=float(rpt.get("cover_title_size", 18))+5, alignment=TA_CENTER,
                                 textColor=col(rpt.get("cover_text_color", "111111")), spaceAfter=4)
    cover_body = ParagraphStyle("coverBody", fontName=font, fontSize=float(rpt.get("cover_text_size", 13)),
                                leading=float(rpt.get("cover_text_size", 13))+8, alignment=TA_RIGHT,
                                textColor=col(rpt.get("cover_text_color", "111111")), spaceAfter=3)
    cover_center = ParagraphStyle("coverCenter", fontName=font, fontSize=float(rpt.get("cover_text_size", 13)),
                                  leading=float(rpt.get("cover_text_size", 13))+7, alignment=TA_CENTER,
                                  textColor=col(rpt.get("cover_text_color", "111111")), spaceAfter=3)

    story=[]
    if cover_visible:
        # Page 1 is rendered entirely by onPage. This guarantees that the
        # editable cover is always exactly one page and data starts on page 2.
        story.extend([NextPageTemplate("DATA"), PageBreak()])

    fields = report_fields(settings)
    if not fields:
        fields=[f for f in settings["fields"] if f.get("enabled",True) and f.get("key")!="registration_date"]

    # Visual order: rightmost = row number, then the selected fields moving left.
    ordered_fields = list(reversed(fields))
    table_fs = float(rpt.get("font_size", 8.2)) if data_size[0] > data_size[1] else float(rpt.get("font_size", 9))
    header_style = ParagraphStyle("tableHead", fontName=font, fontSize=table_fs,
                                  leading=table_fs+1.3, alignment=TA_CENTER,
                                  textColor=table_text)
    cell_style = ParagraphStyle("tableCell", fontName=font, fontSize=max(6.8, table_fs-.3),
                                leading=max(8.0, table_fs+1.0), alignment=TA_RIGHT,
                                textColor=table_text)

    headers=[_report_para(f.get("label", f["key"]), header_style) for f in ordered_fields]
    headers.append(_report_para("#", header_style))
    table_rows=[headers]
    for idx, rec in enumerate(records, 1):
        vals=[_report_para(report_value(rec,f), cell_style) for f in ordered_fields]
        vals.append(_report_para(str(idx), cell_style))
        table_rows.append(vals)

    available=data_size[0]-2*margin-4
    # Weighted widths: long fields get more room; number column remains narrow.
    raw=[]
    for f in ordered_fields:
        key=f.get("key","")
        label=str(f.get("label",key))
        samples=[str(rec.get(key,"")) for rec in records[:30]]
        longest=min(28,max([len(label)]+[len(x) for x in samples] or [6]))
        weight=1.0 + min(2.2,longest/14.0)
        if key in ("name","procedures","result","injury_type"): weight += .8
        raw.append(weight)
    raw.append(.55)
    total=sum(raw)
    widths=[available*x/total for x in raw]
    # Guarantee a readable minimum for every column by redistributing excess.
    minw=28
    if sum(max(minw,w) for w in widths) <= available:
        widths=[max(minw,w) for w in widths]
        extra=available-sum(widths)
        grow=sum(widths[:-1]) or 1
        widths=[w+(extra*w/grow if i<len(widths)-1 else 0) for i,w in enumerate(widths)]

    table=Table(table_rows,colWidths=widths,repeatRows=1,hAlign="CENTER",splitByRow=1)
    style=[
        ("GRID",(0,0),(-1,-1),float(rpt.get("border_width",.6)),col(rpt.get("table_border_color","666666"),"666666")),
        ("BACKGROUND",(0,0),(-1,0),table_head),
        ("TEXTCOLOR",(0,1),(-1,-1),table_text),
        ("VALIGN",(0,0),(-1,-1),"MIDDLE"),
        ("ALIGN",(0,0),(-1,0),"CENTER"),
        ("LEFTPADDING",(0,0),(-1,-1),1.5), ("RIGHTPADDING",(0,0),(-1,-1),1.5),
        ("TOPPADDING",(0,0),(-1,-1),1.8), ("BOTTOMPADDING",(0,0),(-1,-1),1.8),
    ]
    if rpt.get("alternate_rows", True):
        alt=colors.Color(.96,.96,.98)
        for r in range(2,len(table_rows),2): style.append(("BACKGROUND",(0,r),(-1,r),alt))
    table.setStyle(TableStyle(style))
    story.append(table)
    doc.build(story)
    REPORT_FORCE_BOLD = False
    return path


