def export_xlsx(records, settings, stamp=None):
    try:
        from openpyxl import Workbook
        import openpyxl
        from openpyxl.styles import Font, Alignment, Border, Side, PatternFill
        from openpyxl.worksheet.page import PageMargins
    except ImportError as exc:raise RuntimeError("openpyxl غير مثبت. ثبّت openpyxl ثم أعد المحاولة.") from exc
    stamp=stamp or datetime.now().strftime("%Y%m%d_%H%M%S");rpt=settings["report"];fields=report_fields(settings);path=os.path.join(REPORTS_DIR,f"ALBADR_REPORT_{stamp}.xlsx")
    wb=Workbook();ws=wb.active;ws.title="التقرير";ws.sheet_view.rightToLeft=True;cols=max(1,len(fields))
    ws.merge_cells(start_row=1,start_column=1,end_row=1,end_column=cols);ws.cell(1,1,rpt.get("cover_title",rpt.get("title","تقرير"))).font=Font(name="NotoSansArabic",bold=True,size=18);ws.cell(1,1).alignment=Alignment(horizontal="center")
    ws.merge_cells(start_row=2,start_column=1,end_row=2,end_column=cols);ws.cell(2,1,rpt.get("cover_body","")).alignment=Alignment(horizontal="right",wrap_text=True)
    row=4
    for j,f in enumerate(fields,1):
        c=ws.cell(row,j,f.get("label",f["key"]));c.font=Font(name="NotoSansArabic",bold=True);c.fill=PatternFill("solid",fgColor=str(rpt.get("table_header_color","D8EAF4")));c.alignment=Alignment(horizontal="center",vertical="center",wrap_text=True)
    thin=Side(style="thin",color="777777")
    for i,rec in enumerate(records,row+1):
        for j,f in enumerate(fields,1):ws.cell(i,j,report_value(rec,f)).font=Font(name="NotoSansArabic",size=11)
    for rr in ws.iter_rows(min_row=row,max_row=row+len(records),min_col=1,max_col=cols):
        for c in rr:c.border=Border(left=thin,right=thin,top=thin,bottom=thin);c.alignment=Alignment(vertical="top",horizontal="right",wrap_text=True)
    for j in range(1,cols+1):ws.column_dimensions[openpyxl.utils.get_column_letter(j)].width=24
    ws.freeze_panes="A5";ws.auto_filter.ref=f"A4:{openpyxl.utils.get_column_letter(cols)}{row+len(records)}";ws.page_setup.paperSize=ws.PAPERSIZE_A4;ws.page_setup.orientation="landscape";ws.page_margins=PageMargins(left=.25,right=.25,top=.45,bottom=.45);ws.print_title_rows="1:4";wb.save(path);return path


