def _xml_escape(text):return html.escape(str(text or ""),quote=False)
def _docx_para(text,bold=False,size=13,align="right"):
    b="<w:b/>" if bold else "";al="right" if align=="right" else "center" if align=="center" else "left"
    return f'<w:p><w:pPr><w:bidi/><w:jc w:val="{al}"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="NotoSansArabic" w:hAnsi="NotoSansArabic" w:cs="NotoSansArabic"/> {b}<w:sz w:val="{int(float(size)*2)}"/><w:rtl/></w:rPr><w:t xml:space="preserve">{_xml_escape(text)}</w:t></w:r></w:p>'
def _docx_cell(text,bold=False,fill="FFFFFF",size=9):
    return f'<w:tc><w:tcPr><w:shd w:fill="{fill}"/></w:tcPr>{_docx_para(text,bold,size,"right")}</w:tc>'
def _docx_table(headers,rows,fill):
    x='<w:tbl><w:tblPr><w:bidiVisual/><w:tblBorders><w:top w:val="single" w:sz="4"/><w:left w:val="single" w:sz="4"/><w:bottom w:val="single" w:sz="4"/><w:right w:val="single" w:sz="4"/><w:insideH w:val="single" w:sz="4"/><w:insideV w:val="single" w:sz="4"/></w:tblBorders></w:tblPr>';x+='<w:tr>'+''.join(_docx_cell(h,True,fill) for h in headers)+'</w:tr>'
    for row in rows:x+='<w:tr>'+''.join(_docx_cell(v,False,"FFFFFF") for v in row)+'</w:tr>'
    return x+'</w:tbl>'
def export_docx(records,settings,stamp=None):
    stamp=stamp or datetime.now().strftime("%Y%m%d_%H%M%S");rpt=settings["report"];fields=report_fields(settings);path=os.path.join(REPORTS_DIR,f"ALBADR_REPORT_{stamp}.docx")
    W="http://schemas.openxmlformats.org/wordprocessingml/2006/main";R="http://schemas.openxmlformats.org/officeDocument/2006/relationships";REL="http://schemas.openxmlformats.org/package/2006/relationships"
    body=[]
    cover_visible=bool(rpt.get("cover_visible",True))
    if cover_visible:
        body.append(_docx_para(rpt.get("cover_title",rpt.get("title","تقرير")),True,rpt.get("cover_title_size",22),"center"))
        for line in rpt.get("cover_rows",[]) or []:
            if str(line).strip():body.append(_docx_para(line,False,rpt.get("cover_text_size",13),"center"))
        if rpt.get("cover_body"):
            for line in str(rpt["cover_body"]).splitlines():body.append(_docx_para(line,False,rpt.get("cover_text_size",13),"right"))
        body.append(_docx_para("عدد السجلات: "+str(len(records)),True,13,"center"))
    # فاصل مقطع: اتجاه الصفحة الأولى مستقل عن اتجاه صفحات البيانات.
    cover_orient=rpt.get("cover_orientation","portrait");orient=rpt.get("data_orientation",rpt.get("table_orientation","landscape"));
    if cover_orient=="landscape":
        cover_break='<w:pgSz w:w="16838" w:h="11906" w:orient="landscape"/>'
    else:
        cover_break='<w:pgSz w:w="11906" w:h="16838" w:orient="portrait"/>'
    if cover_visible:
        body.append(f'<w:p><w:pPr><w:sectPr>{cover_break}<w:bidi/><w:pgMar w:top="720" w:right="720" w:bottom="720" w:left="720"/><w:headerReference w:type="default" r:id="rIdHeader"/><w:footerReference w:type="default" r:id="rIdFooter"/></w:sectPr></w:pPr></w:p>')
    headers=[f.get("label",f["key"]) for f in fields];rows=[[report_value(rec,f) for f in fields] for rec in records];body.append(_docx_table(headers,rows,str(rpt.get("table_header_color","D8EAF4"))))
    if orient=="landscape":
        sect=f'<w:sectPr><w:pgSz w:w="16838" w:h="11906" w:orient="landscape"/><w:bidi/><w:pgMar w:top="720" w:right="720" w:bottom="720" w:left="720"/><w:headerReference w:type="default" r:id="rIdHeader"/><w:footerReference w:type="default" r:id="rIdFooter"/></w:sectPr>'
    else:
        sect=f'<w:sectPr><w:pgSz w:w="11906" w:h="16838" w:orient="portrait"/><w:bidi/><w:pgMar w:top="720" w:right="720" w:bottom="720" w:left="720"/><w:headerReference w:type="default" r:id="rIdHeader"/><w:footerReference w:type="default" r:id="rIdFooter"/></w:sectPr>'
    docxml=(f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="{W}" xmlns:r="{R}"><w:body>'+"".join(body)+f'{sect}</w:body></w:document>')
    left=" / ".join(map(str,rpt.get("left_lines",[])[:3]));center=" / ".join(map(str,rpt.get("center_lines",[])[:1]));right=" / ".join(map(str,rpt.get("right_lines",[])[:3]));
    header_text="   |   ".join(x for x in [left,center,right] if x)
    footer_text="   |   ".join(x for x in [rpt.get("footer_left",""),rpt.get("footer_center",""),rpt.get("footer_right","")] if x)
    header_xml=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:hdr xmlns:w="{W}" xmlns:r="{R}">'+_docx_para(header_text,False,rpt.get("header_font_size",11),"center")+'</w:hdr>'
    footer_xml=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:ftr xmlns:w="{W}" xmlns:r="{R}">'+_docx_para(footer_text,False,rpt.get("footer_font_size",9),"center")+'</w:ftr>'
    styles=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="{W}"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="NotoSansArabic" w:hAnsi="NotoSansArabic" w:cs="NotoSansArabic" w:eastAsia="NotoSansArabic"/><w:lang w:bidi="ar-SA"/></w:rPr></w:rPrDefault></w:docDefaults></w:styles>'
    rels=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="{REL}"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'
    doc_rels=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="{REL}"><Relationship Id="rIdHeader" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/header" Target="header1.xml"/><Relationship Id="rIdFooter" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/></Relationships>'
    ct=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/word/header1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/><Override PartName="/word/footer1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/></Types>'
    with zipfile.ZipFile(path,"w",zipfile.ZIP_DEFLATED) as z:
        z.writestr("[Content_Types].xml",ct);z.writestr("_rels/.rels",rels);z.writestr("word/document.xml",docxml);z.writestr("word/_rels/document.xml.rels",doc_rels);z.writestr("word/styles.xml",styles);z.writestr("word/header1.xml",header_xml);z.writestr("word/footer1.xml",footer_xml)
    return path


