class ClickableMDCard(MDCard):
    """بطاقة قابلة للنقر دون وراثة ButtonBehavior.

    KivyMD 1.2.0 يجعل MDCard يرث داخليًا من ButtonBehavior، ولذلك فإن
    الجمع بين ButtonBehavior وMDCard يسبب خطأ MRO ويمنع التطبيق من الإقلاع.
    هذا البديل يحافظ على سلوك النقر المطلوب دون تضاعف الوراثة.
    """
    def __init__(self, callback=None, **kwargs):
        self.callback = callback
        self._active_touch = None
        super().__init__(**kwargs)

    def on_touch_down(self, touch):
        if self.collide_point(*touch.pos):
            self._active_touch = touch
            touch.grab(self)
            return True
        return super().on_touch_down(touch)

    def on_touch_up(self, touch):
        grabbed = touch.grab_current is self
        if grabbed:
            touch.ungrab(self)
        if grabbed and self._active_touch is touch:
            self._active_touch = None
            if self.collide_point(*touch.pos):
                self.on_release()
            return True
        return super().on_touch_up(touch)

    def on_release(self):
        if self.callback:
            self.callback()


class HomeServiceCard(ClickableMDCard):
    def __init__(self, title, icon, callback, accent=HOME_RED, subtitle="", **kwargs):
        super().__init__(callback=callback, **kwargs)
        self.orientation = "vertical"
        self.padding = [dp(10), dp(12), dp(10), dp(8)]
        self.spacing = dp(2)
        self.size_hint_y = None
        self.height = dp(148)
        self.radius = [dp(18)] * 4
        self.elevation = 3
        self.md_bg_color = HOME_CARD
        self.ripple_behavior = True
        self.add_widget(MDIcon(icon=icon, theme_text_color="Custom", text_color=accent,
                               font_size=dp(38), size_hint_y=None, height=dp(54)))
        self.add_widget(make_label(title, size="16sp", color=WHITE, halign="center",
                                   bold=True, height=dp(30)))
        if subtitle:
            self.add_widget(make_label(subtitle, size="9sp", color=HOME_MUTED, halign="center",
                                       height=dp(24)))


class HomeNavItem(ButtonBehavior, MDBoxLayout):
    def __init__(self, title, icon, callback, active=False, **kwargs):
        super().__init__(**kwargs)
