def unlock_editor(callback, cancel_callback=None, title="حماية التحرير"):
    s=get_settings(); r=s["report"]; box=MDBoxLayout(orientation="vertical",padding=dp(14),spacing=dp(9))
    box.add_widget(make_label("هذه الصفحة محمية بكلمة مرور",size="18sp",bold=True,halign="center",height=38))
    f=make_field(height=48); f.password=True; box.add_widget(field_group("كلمة المرور",f,True))
    error=make_label("",size="13sp",color=RED,halign="center",height=38); error.opacity=1; box.add_widget(error)
    p=Popup(title=ar(title),content=box,size_hint=(.92,None),height=dp(285),auto_dismiss=False)
    row=MDBoxLayout(orientation="horizontal",spacing=dp(6),size_hint_y=None,height=dp(48))
    ok=MDRaisedButton(text=ar("دخول"),font_name=FONT_NAME,md_bg_color=GOLD,theme_text_color="Custom",text_color=NAVY)
    cancel=MDFlatButton(text=ar("إلغاء"),font_name=FONT_NAME,theme_text_color="Custom",text_color=GRAY)
    state={"attempts":0}
    def check(*_):
        entered = f.get_logical_text().strip()
        expected = str(r.get("password", "ALBDR1") or "ALBDR1").strip()
        if entered and entered == expected:
            p.dismiss()
            Clock.schedule_once(lambda dt: callback(), 0.05)
            return
        state["attempts"] += 1
        f.set_logical_text("")
        f.focus = True
        if state["attempts"] >= 3:
            p.dismiss()
            Clock.schedule_once(lambda dt: password_failed_contact(), 0.05)
            return
        error.text = ar("كلمة المرور غير صحيحة. المحاولة "+str(state["attempts"])+" من 3")
        error.texture_update()
    def cancel_action(*_):
        p.dismiss()
        if cancel_callback: cancel_callback()
    ok.bind(on_release=check); cancel.bind(on_release=cancel_action); row.add_widget(ok);row.add_widget(cancel);box.add_widget(row);p.open()


