    def save_field(self,p,s,i,kf,lf,layout,state):
        key=kf.get_logical_text().strip();label=lf.get_logical_text().strip();
        if not key or not label:popup("تنبيه","أدخل المفتاح واسم الحقل.");return
        if any(ch.isspace() for ch in key):popup("تنبيه","المفتاح الداخلي لا يحتوي على مسافات.");return
        for j,f in enumerate(s["fields"]):
            if f["key"]==key and j!=i:popup("تنبيه","هذا المفتاح مستخدم بالفعل.");return
        if i is not None and s["fields"][i].get("system") and key!="registration_date":popup("تنبيه","تاريخ التسجيل حقل نظامي: يمكن تغيير اسمه فقط، وليس مفتاحه.");return
        cfg={"key":key,"label":label,"required":state["required"],"enabled":state["enabled"],"long":state["long"],"layout":int(layout.text),"system":False,"date":key in ("injury_date","return_date")}
        if key in ("name","procedures"):cfg["layout"]=1
        if i is None:s["fields"].append(cfg)
        else:
            cfg["system"]=s["fields"][i].get("system",False);cfg["date"]=s["fields"][i].get("date",False);s["fields"][i]=cfg
        if save_json(SETTINGS_FILE,s):p.dismiss();self.build()
    def move(self,i,d):
        s=get_settings();j=i+d
        if 0<=j<len(s["fields"]):s["fields"][i],s["fields"][j]=s["fields"][j],s["fields"][i];save_json(SETTINGS_FILE,s);self.build()
    def confirm_delete(self,i):
        s=get_settings();
        if s["fields"][i].get("system"):popup("غير مسموح","تاريخ التسجيل حقل نظامي ولا يمكن حذفه.");return
        popup("حذف الحقل","هل تريد حذف الحقل: "+s["fields"][i]["label"]+"؟",[("حذف",lambda:self.delete(i),RED,WHITE),("إلغاء",None,GRAY,WHITE)])
    def delete(self,i):
        s=get_settings();
        if 0<=i<len(s["fields"]) and not s["fields"][i].get("system"):s["fields"].pop(i);save_json(SETTINGS_FILE,s);self.build()
