# التطبيق
# ============================================================
class ALBADRApp(MDApp):
    def build(self):
        self.theme_cls.theme_style="Dark";self.theme_cls.primary_palette="Amber";self.theme_cls.accent_palette="Amber";self.title=get_settings().get("app_name","ALBADR")
        sm=ScreenManager()
        for cls,name in [(HomeScreen,"home"),(ServicesScreen,"services"),(InputScreen,"input"),(RecordsScreen,"records"),(DetailsScreen,"details"),(ReportsScreen,"reports"),(ReportPreviewScreen,"report_preview"),(ReportEditorScreen,"report_editor"),(SettingsScreen,"settings"),(HomeEditorScreen,"home_editor"),(FieldSettingsScreen,"field_settings")]:sm.add_widget(cls(name=name))
        return sm
    def on_start(self):
        if not os.path.exists(SETTINGS_FILE):save_json(SETTINGS_FILE,clone_default())
        if not os.path.exists(DATA_FILE):save_records([])
        migrate_records()


if __name__=="__main__":
    try:
        ALBADRApp().run()
    except Exception as exc:
        # تسجيل الخطأ في ملف حتى لا تضيع رسالة الانهيار عندما يغلق Pydroid التطبيق.
        try:
            err_path=os.path.join(BASE_DIR,"ALBADR_ERROR.log")
            with open(err_path,"w",encoding="utf-8") as ef:
                ef.write("ALBADR CRASH\n")
                traceback.print_exc(file=ef)
        except Exception:
            pass
        print("\nALBADR CRASH:",repr(exc))
        raise
